const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let csrf='',state,detail,view='home',accountId='',snapshotId,search='',sort='spend',toastTimer;
const labels={library:'本地图库',creatives:'广告与素材',home:'广告平台总览',overview:'Facebook Ads',campaigns:'Facebook 广告系列',recommendations:'优化建议',accounts:'Facebook 广告账户',connection:'数据连接',audit:'操作记录',google:'Google Ads',archive:'全历史采集',combined:'跨平台月报'};
function toast(s,error=false){$('#toast').textContent=s;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,7000);}
async function api(p,opts={}){const r=await fetch(p,{...opts,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...opts.headers}});const data=await r.json();if(!r.ok){if(r.status===401&&p!='/api/login')showLogin();throw new Error(data.error||'请求失败');}return data;}
const post=(p,b={})=>api(p,{method:'POST',body:JSON.stringify(b)});
function showLogin(){$('#app').hidden=true;$('#login').hidden=false;}
const n=(x,d=0)=>x===null||x===undefined||!Number.isFinite(Number(x))?'—':Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const currency=()=>detail?.account.currency||'';
const money=x=>x===null||x===undefined?'—':(currency()==='USD'?'$':currency()+' ')+n(x,2);
const ratio=x=>x===null||x===undefined?'—':n(x,2);
const when=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
function allAccounts(){const map=new Map();for(const s of state.snapshots)for(const a of s.accounts)if(!map.has(a.id))map.set(a.id,a);for(const a of state.settings.discovered_accounts?.accounts||[]){const id=String(a.account_id||a.id).replace(/^act_/,'');if(!map.has(id))map.set(id,{id,name:a.name,currency:a.currency,brand:'API 新发现',totals:{},portfolio:'待核实',availability:'not_synced'});}return [...map.values()];}
let refreshGeneration=0;
async function refresh(preferSnapshot){const request=++refreshGeneration,selected=accountId;creativeRequest++;performanceGeneration++;learningGeneration++;const nextState=await api('/api/state');if(request!==refreshGeneration||selected!==accountId)return;state=nextState;if(preferSnapshot)snapshotId=preferSnapshot;const accounts=allAccounts();if(!accountId&&accounts.length){accountId=accounts[0].id;return refresh(preferSnapshot);}$('#account-select').innerHTML=accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('');$('#account-select').value=selected;const snaps=state.snapshots.filter(s=>s.accounts.some(a=>a.id===selected));if(!snaps.some(s=>s.id===snapshotId))snapshotId=(snaps.find(s=>s.accounts.some(a=>a.id===selected&&Number(a.totals?.spend)>0))||snaps[0])?.id;const selectedSnapshot=snapshotId;if(!selectedSnapshot){detail=null;render();return;}const result=await api(`/api/account?snapshot=${encodeURIComponent(selectedSnapshot)}&account=${encodeURIComponent(selected)}`);if(request!==refreshGeneration||selected!==accountId||selectedSnapshot!==snapshotId)return;detail=result;render();}

function render(){const sn=detail?.snapshot;$('#demo-notice').hidden=!state.demoMode;$('#login').hidden=true;$('#app').hidden=false;$('#breadcrumb').textContent=labels[view];$('#page-title').innerHTML=esc(labels[view])+'<span class="title-dot">.</span>';$('#page-subtitle').textContent=detail?`${detail.account.name} · ${detail.account.portfolio||'业务组合待核实'}`:'账户尚未同步数据';$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const live=sn?.source==='meta_api';$('#mode-pill').textContent=['overview','campaigns','recommendations','accounts'].includes(view)?(live?'Facebook · API 快照':'Facebook · 核查快照'):view==='google'?'Google · 后台 CSV':'双平台工作台';$('#side-status').textContent=state.demoMode?'虚构演示 · 广告写入关闭':'广告写入已关闭';$('#range-button').textContent=sn?sn.since+' — '+sn.until:'选择数据快照';$('#capture-time').textContent=sn?'采集时间 '+when(sn.capturedAt)+(sn.capturePrecision?'（会话近似时间）':''):'';$('#source-banner').className='source-banner'+(live?' api':'');$('#source-banner').innerHTML=`<span class="source-label">${live?'API 数据':'历史核查'}</span><span>${live?(detail.account.availability==='no_delivery_in_range'?'该期间 Meta API 未返回投放记录；可点击日期选择有投放的历史快照。':`此快照由 Meta API 同步，指标采用网站购买口径。${sn.ingestionOrigin==='local_workstation'?'本次由本机采集并写入服务器数据库。':''}`):'历史或演示快照；来源与数据完整性请以记录说明为准。'} ${!state.metaConfigured?'配置 Meta 授权后可同步近期数据。':state.settings.meta_connection?.serverConnectivity==='blocked'?'服务器到 Meta 的网络连接待配置；已有快照仍可查看。':'可点击同步保存新的期间快照。'}</span>`;$('#export').disabled=!detail;$('#sync-button').disabled=state.syncBusy;const facebook=['overview','campaigns','recommendations','accounts'].includes(view);const special=!facebook;$('#range-button').hidden=special;$('#sync-button').hidden=special;$('#export').hidden=special;$('#source-banner').hidden=special;$('.page-heading .eyebrow').textContent='AEPI13-Zaku · '+(facebook?'FACEBOOK ADS / 广告表现':view==='google'?'GOOGLE ADS / 广告表现':'广告运营工作台');$('#facebook-context').hidden=!facebook;document.body.dataset.platform=facebook?'facebook':view==='google'?'google':'all';document.querySelectorAll('.platform-switch button').forEach(b=>{const active=b.dataset.goto===(facebook?'overview':view==='google'?'google':'home');b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('#nav').querySelectorAll('button').forEach(b=>{if(b.dataset.view==='overview'&&facebook)b.classList.add('active');b.setAttribute('aria-current',b.classList.contains('active')?'page':'false');});history.replaceState(null,'','#'+view);if(special)$('#page-subtitle').textContent=view==='home'?'选择平台，查看各自的账户与广告表现。':view==='archive'?'所有可访问账户 · 最大可用历史 · 分批保存与断点续采':view==='google'?'账户 示例 Google 账户 · 历史广告与原始报表':'按同一月份查看各平台，保留各自币种与归因口径';if(special)$('#capture-time').textContent='';renderContent();}
function kpi(label,value,foot,index){return `<article class="kpi"><div class="kpi-label">${label}<span class="kpi-index">0${index}</span></div><div class="kpi-value">${value}</div><p class="kpi-foot">${foot}</p></article>`;}
function table(rows,limit){const shown=limit?rows.slice(0,limit):rows;return `<div class="table-wrap"><table><thead><tr><th>广告系列</th><th>花费</th><th>归因购买</th><th>CPA</th><th>购买金额</th><th>ROAS</th><th>链接点击</th></tr></thead><tbody>${shown.length?shown.map(r=>`<tr data-row="${esc(r.name)}" tabindex="0" aria-label="查看 ${esc(r.name)}"><td><span class="campaign-name" title="${esc(r.name)}">${esc(r.name)}</span><span class="subline">${esc(r.attribution||'归因待核实')}</span></td><td>${money(r.spend)}</td><td>${n(r.purchases)}</td><td>${money(r.cpa)}</td><td>${money(r.purchaseValue)}</td><td class="positive">${ratio(r.roas)}</td><td>${n(r.linkClicks)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">当前快照没有广告系列明细。可接通 Meta 后同步。</td></tr>'}</tbody></table></div>`;}
const typeNames={data:'数据完整性',measurement:'指标口径',setup:'经营目标',review:'需要复核',opportunity:'复测候选'};
function renderContent(){if(view==='library'){renderLibrary();return;}const c=$('#content');if(view==='creatives'){renderCreatives();return;}if(view==='home'){renderHome();return;}if(view==='google'){renderGoogle();return;}if(view==='archive'){renderArchive();return;}if(view==='combined'){renderCombined();return;}if(view==='accounts'){renderAccounts();return;}if(view==='connection'){renderConnection();return;}if(view==='audit'){renderAudit();return;}if(!detail){c.innerHTML='<div class="panel empty"><h3>这个账户还没有数据快照</h3><p>选择同步 Meta 数据，导入该账户的投放记录。</p></div>';return;}
 const {summary:t,campaigns,notes,target}=detail.analysis;
 if(view==='overview'){
 const sorted=[...campaigns].sort((a,b)=>(b.spend||0)-(a.spend||0));const max=sorted[0]?.spend||1;
 c.innerHTML=`<div class="kpi-grid">${kpi('广告花费',money(t.spend),'账户原生总计 · '+esc(currency()),1)}${kpi('归因购买',n(t.purchases),'Meta 归因次数，非去重订单',2)}${kpi('每次购买成本',money(t.cpa),'广告花费 ÷ 归因购买',3)}${kpi('广告投入回报',ratio(t.roas),'购买金额 '+money(t.purchaseValue)+' · 非净利润',4)}</div><div class="mini-metrics"><div><small>展示次数 / IMPRESSIONS</small><strong>${n(t.impressions)}</strong></div><div><small>链接点击 / LINK CLICKS</small><strong>${n(t.linkClicks)}</strong></div><div><small>链接点击率 / CTR</small><strong>${t.ctr===null?'—':n(t.ctr,2)+'%'}</strong></div></div><div class="overview-grid"><article class="panel"><div class="panel-head"><div><h2>预算花在哪里</h2><p class="muted">当前已载入的广告系列 · 按花费排序</p></div><span class="tag gray">${campaigns.length} 条明细</span></div><div class="spend-rows">${sorted.slice(0,6).map(r=>`<div class="spend-row"><div class="spend-row-head"><span class="name" title="${esc(r.name)}">${esc(r.name)}</span><strong>${money(r.spend)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,r.spend/max*100).toFixed(2)}%"></div></div></div>`).join('')||'<p class="empty">尚无明细</p>'}</div><p class="panel-note">${detail.account.campaignsComplete?'API 已完成该次查询分页。':'仅展示已核查明细，不代表完整账户预算分布。'}未提供日趋势时不绘制推测曲线。</p></article><article class="panel"><div class="panel-head"><div><h2>本次数据需要留意</h2><p class="muted">决策前先检查数据与口径</p></div><span class="tag">${notes.length} 项</span></div><div class="insight-list">${notes.slice(0,3).map(i=>`<div class="insight"><span class="label">${typeNames[i.kind]}</span><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p></div>`).join('')}</div></article></div><article class="panel table-panel"><div class="panel-head"><div><h2>重点广告系列</h2><p class="muted">点击查看指标与归因说明</p></div><button class="text-button" data-goto="campaigns">查看全部 →</button></div>${table(sorted,5)}<div class="table-footer"><span>${detail.account.campaignsComplete?'本次同步明细':'当前为部分历史明细'} · 不同归因窗口不直接比较</span><span>${esc(detail.snapshot.since)} — ${esc(detail.snapshot.until)}</span></div></article>`;
 }else if(view==='campaigns'){
 c.innerHTML=`<div class="table-toolbar"><input id="campaign-search" placeholder="搜索广告系列名称…" aria-label="搜索广告系列" value="${esc(search)}"><select id="campaign-sort" aria-label="排序"><option value="spend">花费：从高到低</option><option value="purchases">购买：从高到低</option><option value="roas">ROAS：从高到低</option><option value="cpa">CPA：从低到高</option></select></div><div class="notice warning">${detail.account.campaignsComplete?'明细已完成 API 分页。':'当前仅保留浏览器核查时可见的 '+campaigns.length+' 条明细，并非账户全部广告。'} 排序只调整展示顺序，不代表可直接扩量或暂停。</div><article class="panel table-panel"><div id="campaign-table"></div><div class="table-footer"><span id="row-count"></span><span>点击任意一行查看详情 →</span></div></article>`;$('#campaign-sort').value=sort;renderCampaignRows();
 }else if(view==='recommendations'){
 c.innerHTML=`<article class="panel"><div class="panel-head"><div><h2>让建议对准你的经营目标</h2><p class="muted">当前目标 CPA：${money(target.targetCpa)}　/　ROAS：${ratio(target.targetRoas)}</p></div><button class="secondary" id="set-target">设置目标</button></div><div class="notice">建议由可解释的指标规则生成；未调用大模型。历史快照只用于回顾与制定复测计划，保存方案不会修改广告。</div></article><div class="recommendation-grid" style="margin-top:18px">${notes.map(i=>`<article class="panel"><span class="tag ${i.kind==='opportunity'?'green':i.kind==='review'?'red':''}">${typeNames[i.kind]}</span><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p>${i.campaign?`<button class="secondary" data-detail="${esc(i.campaign)}">查看指标与保存方案 →</button>`:''}</article>`).join('')}</div><article class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>待审阅优化方案</h2><p class="muted">每一项保留来源、范围与操作记录</p></div><span class="tag gray">不执行投放修改</span></div><div id="plans-list">加载中…</div></article>`;loadPlans();
 }
}
function renderCampaignRows(){let rows=detail.analysis.campaigns.filter(r=>r.name.toLowerCase().includes(search.toLowerCase()));rows.sort((a,b)=>sort==='cpa'?(a.cpa??Infinity)-(b.cpa??Infinity):(b[sort]??-Infinity)-(a[sort]??-Infinity));$('#campaign-table').innerHTML=table(rows);$('#row-count').textContent=`显示 ${rows.length} / ${detail.analysis.campaigns.length} 条已载入明细`;}
function renderAccounts(){const accounts=allAccounts();if(!accountId&&accounts.length){accountId=accounts[0].id;return refresh(preferSnapshot);}$('#content').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>所有可见广告账户</h2><p class="muted">${accounts.length} 个账户 · 按业务组合及广告内容核对品牌归属</p></div><button class="secondary" id="discover">刷新 API 账户列表</button></div><div class="table-wrap"><table><thead><tr><th>广告账户 / ID</th><th>业务组合</th><th>品牌核查</th><th>已记录花费</th><th>数据状态</th></tr></thead><tbody>${accounts.map(a=>`<tr data-account="${esc(a.id)}" tabindex="0"><td><strong>${esc(a.name)}</strong><span class="subline">${esc(a.id)}</span></td><td>${esc(a.portfolio||'待核实')}</td><td class="wrap">${esc(a.brand||'待分类')}</td><td>${a.currency==='USD'?'$':esc(a.currency||'')}${n(a.totals?.spend,2)}</td><td><span class="tag ${/delivery$/.test(a.availability)?'green':'gray'}">${a.availability==='no_delivery_in_range'?'该期间未显示投放':a.availability==='not_synced'?'尚未同步':'已有数据'}</span></td></tr>`).join('')}</tbody></table></div><p class="panel-note">花费来自各账户最新已存快照，日期可能不同；不进行跨期间、跨币种简单相加。点击账户可切换。</p></div>`;}
function renderConnection(){$('#content').innerHTML=`<div class="settings-grid"><article class="panel"><div class="panel-head"><div><h2>Meta Marketing API</h2><p class="muted">使用官方 API 授权，通过开源 MCP 获取数据</p></div><span class="tag ${state.metaConfigured?'green':''}">${state.settings.meta_connection?.serverConnectivity==='connected'?'服务器同步已验证':state.metaConfigured?'凭据已配置，待同步验证':'待配置授权'}</span></div><div class="status-line"><span>数据存储</span><strong>${state.storage==='postgres'?'PostgreSQL':'内存测试模式'}</strong></div><div class="status-line"><span>服务器出网</span><strong>${state.settings.meta_connection?.serverConnectivity==='connected'?'最近连接检查成功':state.settings.meta_connection?.serverConnectivity==='blocked'?'待配置到 Meta 的网络连接':'尚待成功同步验证'}</strong></div><div class="status-line"><span>令牌到期时间</span><strong>${state.settings.meta_connection?.tokenExpiresAt?when(state.settings.meta_connection.tokenExpiresAt*1000):'待验证'}</strong></div><div class="status-line"><span>广告写入</span><strong>第一版仅保存方案</strong></div><div class="status-line"><span>开源接口版本</span><strong>Meta Ads MCP v2.0.0</strong></div><div class="status-line"><span>源代码</span><a href="https://github.com/getmcpads-com/meta-ads-mcp-server" target="_blank" rel="noreferrer">查看 GitHub ↗</a></div><p class="fine" style="margin-top:20px">浏览器登录会话与 API 凭据独立。此页面不接收或显示 Token；服务器通过私密环境文件读取。</p><button class="secondary" id="discover">验证授权并发现账户</button></article><article class="panel"><h2>连接步骤</h2><p class="muted">只需一次配置，即可持续保存投放快照。</p><div class="step"><span>01</span><div><strong>准备 Meta 应用和账户权限</strong><p>在 Meta Business Settings 中将需要分析的广告账户分配给应用 / 系统用户。</p></div></div><div class="step"><span>02</span><div><strong>生成只读访问令牌</strong><p>授予 ads_read。资产发现可能另需 business_management，取决于账户归属和授权。</p></div></div><div class="step"><span>03</span><div><strong>配置服务器私密环境文件</strong><p>在私密环境配置中设置 META_ACCESS_TOKEN，然后重新创建工作台容器；请勿将令牌发到聊天或填入前端代码。</p></div></div><div class="step"><span>04</span><div><strong>验证并同步</strong><p>点击“验证授权并发现账户”，再按账户和日期同步。返回成功后才会标记为 API 数据快照。</p></div></div><a class="text-button" href="https://developers.facebook.com/docs/marketing-apis/get-started/" target="_blank" rel="noreferrer">Meta 官方接入文档 ↗</a></article></div>`;}
async function renderAudit(){const c=$('#content');c.innerHTML='<article class="panel"><h2>操作记录</h2><p class="muted">正在读取数据库日志…</p></article>';try{const rows=await api('/api/audit');if(view!=='audit')return;c.innerHTML=`<article class="panel"><div class="panel-head"><div><h2>操作记录</h2><p class="muted">登录、目标更新、同步和方案保存均留痕</p></div><span class="tag gray">最近 100 条</span></div>${rows.map(r=>`<div class="audit-row"><strong>${esc(({login:'登录工作台',target_updated:'更新经营目标',sync_completed:'同步完成',accounts_discovered:'发现账户',proposal_created:'保存优化方案',learning_record_saved:'追加学习复盘记录'})[r.event]||r.event)}</strong><small class="muted">　${when(r.created_at)}</small><p>${esc(JSON.stringify(r.payload))}</p></div>`).join('')||'<p class="empty">暂无操作记录</p>'}</article>`;}catch(e){toast(e.message,true);}}
async function loadPlans(){try{const rows=await api('/api/plans');if(!$('#plans-list'))return;$('#plans-list').innerHTML=rows.filter(r=>r.accountId===accountId).map(r=>`<div class="audit-row"><span class="tag gray">待审阅</span><strong> ${esc(r.campaignName)}</strong><p>${esc(({review:'复核',retest:'复测',reduce:'评估减量',increase:'评估扩量'})[r.action])} · ${esc(r.note||'未填写备注')}<br>${esc(r.since)} — ${esc(r.until)} · ${when(r.createdAt)}</p></div>`).join('')||'<p class="empty">暂无方案。在广告系列详情中保存复核或复测计划。</p>';}catch(e){toast(e.message,true);}}
function openDetail(name){const r=detail.analysis.campaigns.find(r=>r.name===name);if(!r)return;$('#detail-content').innerHTML=`<div class="dialog-title"><h2>广告系列详情</h2><button class="close" data-close="detail-dialog" aria-label="关闭">×</button></div><h3 style="overflow-wrap:anywhere">${esc(r.name)}</h3><span class="tag gray">${detail.snapshot.source==='meta_api'?'API 数据':'历史快照'}</span><div class="detail-grid"><div><small>花费</small><strong>${money(r.spend)}</strong></div><div><small>归因购买</small><strong>${n(r.purchases)}</strong></div><div><small>每次购买成本</small><strong>${money(r.cpa)}</strong></div><div><small>ROAS</small><strong>${ratio(r.roas)}</strong></div></div><p class="fine">归因：${esc(r.attribution)}<br>日期：${esc(detail.snapshot.since)} — ${esc(detail.snapshot.until)}<br>购买金额：${money(r.purchaseValue)} · 链接点击：${n(r.linkClicks)}<br>${r.id?'系列 ID：'+esc(r.id):'当前快照没有广告系列 ID、当前预算及投放状态，不能执行投放修改。'}</p><p><button class="secondary" data-campaign-creatives="${esc(r.id||'')}">查看此系列广告图片 →</button></p><label>方案备注<textarea id="plan-note" rows="3" placeholder="写下需要复核的原因、复测素材或预期目标…" maxlength="1500"></textarea></label><p class="fine" style="margin-top:12px">以下操作仅保存待审阅方案，不调整预算、不暂停广告。</p><div class="plan-actions">${[['review','保存复核方案'],['retest','保存复测方案'],['increase','记录扩量意向'],['reduce','记录减量意向']].map(([a,t])=>`<button class="secondary" data-plan="${a}" data-name="${esc(name)}">${t}</button>`).join('')}</div>`;$('#detail-dialog').showModal();}
async function boot(){if(labels[location.hash.slice(1)])view=location.hash.slice(1);try{const s=await api('/api/session');csrf=s.csrf;await refresh();}catch{showLogin();}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));const button=e.target.querySelector('button');button.disabled=true;try{const r=await post('/api/login',b);csrf=r.csrf;$('#login-error').textContent='';e.target.password.value='';await refresh();}catch(err){$('#login-error').textContent=err.message;}finally{button.disabled=false;}});
$('#account-select').addEventListener('change',async e=>{accountId=e.target.value;snapshotId=null;search='';await refresh().catch(e=>toast(e.message,true));});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(state&&labels[next]){view=next;render();}});
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render();}});
$('#export').addEventListener('click',()=>{if(detail)location.href=`/api/export?snapshot=${encodeURIComponent(snapshotId)}&account=${encodeURIComponent(accountId)}`;});
$('#logout').addEventListener('click',async()=>{await post('/api/logout');showLogin();});
$('#range-button').addEventListener('click',()=>{$('#snapshot-list').innerHTML=state.snapshots.filter(s=>s.accounts.some(a=>a.id===accountId)).map(s=>`<button class="snapshot-item" data-snapshot="${esc(s.id)}"><strong>${esc(s.since)} — ${esc(s.until)}</strong><br><span class="tag ${s.source==='meta_api'?'green':''}">${s.source==='meta_api'?'API 同步':'浏览器核查快照'}</span> <small>${when(s.capturedAt)}</small></button>`).join('')||'<p class="empty">这个账户尚无快照</p>';$('#snapshot-dialog').showModal();});
$('#sync-button').addEventListener('click',()=>{const f=$('#sync-form');const until=state.today;f.until.value=until;f.since.value=new Date(Date.parse(until)-29*86400000).toISOString().slice(0,10);f.until.max=until;$('#sync-connection').innerHTML=state.metaConfigured?'<div class="notice">账户 '+esc(accountId)+' · 将使用统一归因同步。</div>':'<div class="notice warning">Meta API 授权尚未配置。请到“数据连接”查看配置步骤，当前不能同步。</div>';$('#sync-submit').disabled=!state.metaConfigured;$('#sync-dialog').showModal();});
$('#sync-form').addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));$('#sync-submit').disabled=true;$('#sync-submit').textContent='同步中…';try{const r=await post('/api/sync',{...b,accountId});$('#sync-dialog').close();await refresh(r.snapshotId);toast('同步成功，已保存新快照');}catch(err){toast(err.message,true);}finally{$('#sync-submit').disabled=false;$('#sync-submit').textContent='开始同步';}});
$('#target-form').addEventListener('submit',async e=>{e.preventDefault();try{await post('/api/settings',{...Object.fromEntries(new FormData(e.target)),accountId});$('#target-dialog').close();await refresh();toast('经营目标已保存');}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='campaign-search'){search=e.target.value;renderCampaignRows();}});document.addEventListener('change',e=>{if(e.target.id==='campaign-sort'){sort=e.target.value;renderCampaignRows();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-row]'))openDetail(e.target.dataset.row);if(e.key==='Enter'&&e.target.matches('tr[data-account]'))e.target.click();});
document.addEventListener('click',async e=>{try{
 const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}
 const go=e.target.closest('[data-goto]');if(go){view=go.dataset.goto;render();return;}
 const row=e.target.closest('[data-row],[data-detail]');if(row){openDetail(row.dataset.row||row.dataset.detail);return;}
 const ac=e.target.closest('[data-account]');if(ac){accountId=ac.dataset.account;snapshotId=null;view='overview';await refresh();return;}
 const snap=e.target.closest('[data-snapshot]');if(snap){snapshotId=snap.dataset.snapshot;$('#snapshot-dialog').close();await refresh();return;}
 if(e.target.closest('#set-target')){const t=detail.analysis.target;$('#target-form').targetCpa.value=t.targetCpa??'';$('#target-form').targetRoas.value=t.targetRoas??'';$('#target-dialog').showModal();return;}
 if(e.target.closest('#discover')){const b=e.target.closest('#discover');b.disabled=true;b.textContent='验证中…';try{const r=await post('/api/discover');await refresh();toast('授权验证成功，发现 '+r.accounts.length+' 个账户');}finally{b.disabled=false;}return;}
 const plan=e.target.closest('[data-plan]');if(plan){plan.disabled=true;try{await post('/api/plans',{snapshotId,accountId,campaignName:plan.dataset.name,action:plan.dataset.plan,note:$('#plan-note').value});$('#detail-dialog').close();toast('方案已保存，未修改广告');if(view==='recommendations')loadPlans();}finally{plan.disabled=false;}}
}catch(err){toast(err.message,true);}});
const creativeNav=document.createElement('button');creativeNav.dataset.view='creatives';creativeNav.textContent='广告与素材';$('#nav').querySelector('[data-view=campaigns]').after(creativeNav);
boot();

let archiveTimer;
const statusLabel={pending:'排队中',running:'采集中',complete:'已保存',failed:'需处理',unavailable:'平台限制'};
async function renderArchive(){
 clearTimeout(archiveTimer);const c=$('#content');c.innerHTML='<article class="panel"><p>读取全历史采集进度…</p></article>';
 try{const data=await api('/api/archive');if(view!=='archive')return;
 const totals=data.summary.reduce((a,r)=>{a.tasks+=Number(r.tasks);a.rows+=Number(r.rows);if(r.status==='complete')a.done+=Number(r.tasks);if(['failed','unavailable'].includes(r.status))a.failed+=Number(r.tasks);return a;},{tasks:0,rows:0,done:0,failed:0});
 c.innerHTML=`<article class="panel"><div class="panel-head"><div><h2>全部账户 · 最大可用历史</h2><p class="muted">按平台、账户、数据类型及日期分批存入 PostgreSQL，重启后从已保存游标继续。</p></div><div class="heading-actions"><button class="primary" data-archive-start="meta">采集全部 Facebook</button><button class="secondary" data-archive-start="google" ${state.googleConfigured?'':'disabled'}>采集全部 Google</button></div></div><p class="notice">Google 授权：${state.googleConfigured?'凭据已配置，读取时验证':'尚待完成 API 授权'}。采集范围包括账户、系列、广告组／广告集、广告、素材及可用表现明细；搜索词和商品数据按平台权限返回。素材元数据与原文件分别归档；图片原文件的已完成、待处理及失败数量见下方，图片与视频原文件按下方已校验数量显示，待处理项不计入完成。</p><p class="fine">Google 早期月度统计最多保留 11 年，细粒度数据最多 37 个月；Meta 按 API maximum 返回边界采集，明细查询受 37 个月滚动保留期限限制。平台已删除、过期、隐私隐藏及无权限数据无法恢复。失败任务单独列出，不会标记为已完成。</p></article><div class="kpi-grid" style="margin-top:18px">${kpi('已保存记录',n(totals.rows),'各数据集行数，不能相加为订单数',1)}${kpi('已完成批次',n(totals.done),'/ '+n(totals.tasks)+' 批次',2)}${kpi('需处理批次',n(totals.failed),'权限、平台限制或请求失败',3)}${kpi('采集平台',n(new Set(data.tasks.map(t=>t.platform)).size),'按可访问账户发现结果',4)}</div>${renderMediaArchive(data.mediaSummary)}<article class="panel"><div class="panel-head"><h2>采集批次</h2><button class="secondary" id="retry-archive">重试失败批次</button></div><div class="table-wrap"><table><thead><tr><th>平台 / 账户</th><th>数据集</th><th>日期</th><th>状态</th><th>记录数</th><th>详情</th></tr></thead><tbody>${data.tasks.map(t=>`<tr><td>${t.platform==='google'?'Google':'Facebook'}<span class="subline">${esc(t.account_id)}</span></td><td>${esc(t.kind)}</td><td>${esc(t.spec.since||'最大可用')} — ${esc(t.spec.until||'')}</td><td><span class="tag ${t.status==='complete'?'green':t.status==='failed'?'red':'gray'}">${statusLabel[t.status]}</span></td><td>${n(t.rows_count)}</td><td class="wrap">${t.error?esc(t.error):Number(t.rows_count)>0?`<button class="text-button" data-archive-task="${esc(t.id)}">查看原始记录 →</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">还没有采集任务。点击上方按钮开始全账户采集。</td></tr>'}</tbody></table></div><p class="panel-note">显示最近更新的 300 个批次；顶部计数覆盖全部批次。数据集有不同粒度，请勿混加。</p></article>`;
 archiveTimer=setTimeout(()=>{if(view==='archive')renderArchive();},12000);
 }catch(e){c.innerHTML='<article class="panel"><p>'+esc(e.message)+'</p></article>';}
}
function googleReport(){return (state.settings.google_browser_exports?.exports||[]).find(r=>r.kind==='campaigns')||(state.settings.google_browser_exports?.exports||[])[0];}
function googleNumber(v){if(v===null||v===undefined||v==='')return null;const value=Number(String(v).replaceAll(',',''));return Number.isFinite(value)?value:null;}
function renderHome(){const g=googleReport(),gt=g?.nativeTotal,fb=detail?.analysis.summary;const fbName=detail?.account.name||'选择账户';$('#content').innerHTML=
 '<div class="platform-grid">'+
 '<article class="platform-card facebook-card"><div class="platform-card-title"><span class="platform-letter facebook-letter large">f</span><div><h2>Facebook Ads</h2><p>Facebook / Instagram 广告</p></div><span class="tag green">'+allAccounts().length+' 个账户</span></div><div class="platform-data-context">当前账户 <strong>'+esc(fbName)+'</strong><span>'+esc(detail?.snapshot.since||'')+' — '+esc(detail?.snapshot.until||'')+'</span></div><div class="platform-stats"><div><span>广告花费</span><strong>'+money(fb?.spend)+'</strong></div><div><span>网站购买</span><strong>'+n(fb?.purchases)+'</strong></div><div><span>ROAS</span><strong>'+ratio(fb?.roas)+'</strong></div></div><p class="platform-caption">当前账户所选历史快照；其他账户在平台内切换。</p><div class="platform-card-actions"><button class="primary facebook-button" data-goto="overview">查看 Facebook 广告 →</button><button class="text-button" data-goto="accounts">全部账户</button></div></article>'+
 '<article class="platform-card google-card"><div class="platform-card-title"><span class="platform-letter google-letter large">G</span><div><h2>Google Ads</h2><p>搜索 / 展示 / 视频广告</p></div><span class="tag gray">后台报表</span></div><div class="platform-data-context">广告账户 <strong>'+esc(g?.accountId||'尚无归档')+'</strong><span>'+esc(g?.since||'')+' — '+esc(g?.until||'')+'</span></div><div class="platform-stats"><div><span>广告花费 · '+esc(gt?.['Currency code']||'')+'</span><strong>'+n(googleNumber(gt?.Cost),2)+'</strong></div><div><span>广告系列</span><strong>'+n(g?.entityRows)+'</strong></div><div><span>展示次数</span><strong>'+n(googleNumber(gt?.['Impr.']))+'</strong></div></div><p class="platform-caption">账户状态以当前授权查询为准；报表与实时API连接分开核对。</p><div class="platform-card-actions"><button class="primary google-button" data-goto="google">查看 Google 广告 →</button><button class="text-button" data-goto="archive">采集状态</button></div></article></div>'+
 '<article class="panel workspace-tools"><div><h2>跨平台管理</h2><p class="muted">分别保留平台、币种和转化定义，避免把两边的转化重复相加。</p></div><div class="tool-links"><button class="secondary" data-goto="combined">查看月度对照 →</button><button class="secondary" data-goto="archive">采集进度与素材 →</button></div></article>';
}
function renderGoogle(){const g=googleReport(),t=g?.nativeTotal;const saved=state.settings.google_accounts;$('#content').innerHTML=
 '<div class="google-account-strip"><div><span class="platform-letter google-letter">G</span><strong>Google Ads</strong><span>账户 '+esc(g?.accountId||'尚未归档')+'</span></div><span class="tag gray">历史报表 · 状态需核实</span></div>'+
 '<div class="kpi-grid google-kpis">'+kpi('广告花费 · '+esc(t?.['Currency code']||''),n(googleNumber(t?.Cost),2),'账户原生总计 · 后台 CSV',1)+kpi('展示次数',n(googleNumber(t?.['Impr.'])),'所选报表期间',2)+kpi('互动次数',n(googleNumber(t?.Interactions)),'包含不同广告类型的互动',3)+kpi('广告系列',n(g?.entityRows),'已归档系列明细',4)+'</div>'+
 '<p class="platform-caption">报表期间 '+esc(g?.since||'—')+' — '+esc(g?.until||'—')+'。转化次数缺失时显示 —；转化金额按 Google 账户目标定义。</p>'+
 renderGoogleBrowserReports()+
 '<details class="panel connection-details"><summary>Google 账户连接与采集状态</summary><p class="notice warning">账户权限、状态及API可读性需要独立验证；已有报表不证明当前连接可用，本程序不启用账户。</p><p class="muted">Google 适配器需独立配置和验证。已记录账户发现 '+n(saved?.accounts?.length||0)+' 个；授权配置与历史报表独立保存。</p><div class="heading-actions"><button class="secondary" id="google-discover" '+(state.googleConfigured?'':'disabled')+'>刷新账户发现</button><button class="secondary" data-goto="archive">查看采集详情</button><button class="secondary" data-goto="connection">连接设置</button></div></details>';
}
let reportMonth='';
async function renderCombined(){reportMonth||=state.today.slice(0,7);const c=$('#content');c.innerHTML=`<article class="panel"><div class="panel-head"><h2>跨平台月报</h2><label>月份<input id="report-month" type="month" value="${esc(reportMonth)}" max="${esc(state.today.slice(0,7))}"></label></div><p class="muted">从已归档数据按同一月份查询，保留账户币种与不同转化口径。</p><div id="combined-report">读取中…</div></article>`;
 try{const r=await api('/api/report?month='+reportMonth);if(view!=='combined'||r.month!==reportMonth)return;$('#combined-report').innerHTML=`<p class="notice">${esc(r.note)}</p><div class="table-wrap"><table><thead><tr><th>平台 / 账户</th><th>币种</th><th>花费</th><th>点击</th><th>转化口径</th><th>转化次数</th><th>转化金额</th><th>ROAS</th><th>归档状态</th></tr></thead><tbody>${r.accounts.map(a=>`<tr><td>${a.platform==='google'?'Google':'Facebook'} · ${esc(a.name)}<span class="subline">${esc(a.id)}</span></td><td>${esc(a.currency||'待核实')}</td><td>${n(a.spend,2)}</td><td>${n(a.clicks)}</td><td>${a.platform==='google'?'主要转化（待核对购买目标）':'网站购买'}</td><td>${n(a.conversions,2)}</td><td>${n(a.conversionValue,2)}</td><td>${ratio(a.roas)}</td><td>${a.coverageComplete?'此批次已归档':'批次未齐全'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">此月尚无已归档数据，不能据此判断零投放。请到“全历史采集”查看进度。</td></tr>'}</tbody></table></div>`;}catch(e){if($('#combined-report'))$('#combined-report').textContent=e.message;}
}
document.addEventListener('change',e=>{if(e.target.id==='report-month'){reportMonth=e.target.value;renderCombined();}});
document.addEventListener('click',async e=>{const start=e.target.closest('[data-archive-start]');try{
 if(start){start.disabled=true;start.textContent='正在发现账户…';await post('/api/archive/start',{platform:start.dataset.archiveStart});view='archive';await refresh();toast('全账户采集已排队，服务器会持续保存批次');}
 if(e.target.closest('#google-discover')){const b=e.target.closest('#google-discover');b.disabled=true;await post('/api/google/discover');await refresh();toast('Google 账户发现完成');}
 if(e.target.closest('#retry-archive')){await post('/api/archive/retry');await renderArchive();toast('失败批次已重新排队');}
 const task=e.target.closest('[data-archive-task]');if(task){const rows=await api('/api/archive/page?task='+encodeURIComponent(task.dataset.archiveTask));$('#detail-content').innerHTML='<div class="dialog-title"><h2>原始归档记录 · 一页</h2><button class="close" data-close="detail-dialog" aria-label="关闭">×</button></div><p class="fine">数据集：'+esc(task.dataset.archiveTask)+'</p><a class="text-button" href="/api/archive/export?task='+encodeURIComponent(task.dataset.archiveTask)+'">下载此批次全部记录 ↓</a><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:60vh;overflow:auto">'+esc(JSON.stringify(rows[0]?.payload,null,2))+'</pre>';$('#detail-dialog').showModal();}
 }catch(err){toast(err.message,true);if(start){start.disabled=false;start.textContent='重新开始采集';}}
});

function renderGoogleBrowserReports(){
 const exports=state.settings.google_browser_exports?.exports||[];
 const connection=state.settings.google_connection;
 const warning=connection?.oauthPublishingStatus==='testing'?'<article class="panel" style="margin-top:18px"><p class="notice warning">Google OAuth 当前为测试状态，离线刷新令牌受 7 天有效期限制。完成生产品牌配置并重新授权后才能长期自动采集；已归档数据不会过期。</p></article>':'';
 return exports.map(report=>{const t=report.nativeTotal;const names=['Campaign','Ad group','Ad','Search term','Keyword','Asset'];return `<article class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Google 广告系列 · 历史报表</h2><p class="muted">${esc(report.accountId)} · ${esc(report.since)} — ${esc(report.until)} · ${n(report.entityRows)} 条明细</p></div><a class="text-button" href="/api/archive/export?task=${encodeURIComponent(report.id)}">下载完整记录 ↗</a></div><p class="notice">${esc(report.coverage)}。转化金额按 Google 账户目标定义，不能视为去重购买金额。</p>${t?`<p>账户原生总计：花费 ${esc(t['Currency code']||'')} ${esc(t.Cost||'—')} · 展示 ${esc(t['Impr.']||'—')} · 转化次数 ${esc(t.Conversions||'—')} · 转化金额 ${esc(t['Conv. value']||'—')}</p>`:''}<div class="table-wrap"><table><thead><tr><th>明细</th><th>状态</th><th>展示</th><th>互动 / 点击</th><th>花费</th><th>转化金额</th></tr></thead><tbody>${(report.preview||[]).map(row=>`<tr><td class="wrap">${esc(names.map(k=>row[k]).filter(Boolean).join(' / ')||row[Object.keys(row)[0]]||'—')}</td><td>${esc(row.Status||row['Campaign status']||row['Ad group status']||'—')}</td><td>${esc(row['Impr.']||'—')}</td><td>${esc(row.Clicks||row.Interactions||'—')}</td><td>${esc(row['Currency code']||'')} ${esc(row.Cost||'—')}</td><td>${esc(row['Conv. value']||'—')}</td></tr>`).join('')}</tbody></table></div><p class="panel-note">显示前 ${n(Math.min(report.entityRows,100))} 条，完整明细及总计保存在原始记录中。NAS 已校验：${esc(report.nasRelativePath)}；分享链接${report.shareLinkStatus==='pending_share_link'?'待补充':'已记录'}。</p></article>`;}).join('')+warning;
}

function renderMediaArchive(rows=[]){
 if(!rows.length)return '';
 return `<article class="panel" style="margin:18px 0"><h2>广告素材文件 · 下载与归档</h2><p class="muted">素材原文件由服务器受控Worker下载到本机，任务保留断点；NAS用于版本备份。下表是下载任务状态，备份结果在本地图库另行显示。原始文件保留，逐项校验哈希。</p><div class="table-wrap"><table><thead><tr><th>类型</th><th>状态</th><th>文件数</th><th>已验证大小</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.kind==='video'?'视频':'图片'}</td><td>${statusLabel[r.status]||esc(r.status)}</td><td>${n(r.files)}</td><td>${n(Number(r.bytes)/1024/1024,2)} MB</td></tr>`).join('')}</tbody></table></div><p class="panel-note">主存储：服务器本地；NAS：独立版本备份。原始链接、账户关联、文件路径与哈希保存在PostgreSQL。<button class="text-button" data-open-local-library>查看本地图库与备份状态 →</button></p></article>`;
}

// Advertising preview is independent of delivery snapshots (includes scheduled ads).
let creativeRows=[],creativeAfter=null,creativeComplete=false,creativeAccount='',creativeQuery='',creativeCampaign='',creativeRequest=0;
async function renderCreatives(more=false,force=false){
 const request=++creativeRequest,selected=accountId,c=$('#content');
 if(!more){performanceGeneration++;performanceState={status:'loading',rows:new Map()};creativeRows=[];creativeAfter=null;creativeComplete=false;creativeAccount=selected;
  c.innerHTML=`<article class="panel"><div class="panel-head"><div><h2>广告与素材 · 投放学习案例</h2><p class="muted">看素材、理解设置、按日期复盘调整理由与结果。0.1.0-preview.2 · 2026-10-28（太平洋时间）</p></div><button class="secondary" id="creative-refresh">重新读取</button></div><label>广告账户<select id="creative-account">${allAccounts().map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${esc(a.id)}</option>`).join('')}</select></label><div class="table-toolbar" style="margin-top:16px"><input id="creative-search" aria-label="搜索广告或素材" placeholder="搜索广告名称、广告ID或文案" value="${esc(creativeQuery)}"><button class="secondary" id="creative-clear">显示全部系列</button></div><p id="creative-context" class="fine"></p><p id="daily-review-state" class="notice">正在读取服务器每日复盘状态…</p><p id="creative-source" class="notice">正在只读获取 Meta 广告与素材…</p>${performanceControls()}<div id="creative-grid" class="creative-grid"></div><p id="creative-count" class="fine"></p><button class="secondary" id="creative-more" hidden>加载更多广告</button><p class="fine">素材来自当前 Meta 创意关联，与历史投放指标日期独立；动态素材可能包含多个版本，不表示每个版本都已投放。图片链接失效时会显示提示，不用其他图片代替。</p></article>`;
 }
 if(!more)loadDailyReviewState(selected,request);
 try{const data=await api('/api/creatives?account='+encodeURIComponent(selected)+(more?'&after='+encodeURIComponent(creativeAfter):'')+(force?'&refresh=1':''));if(view!=='creatives'||request!==creativeRequest||selected!==creativeAccount)return;
  const ids=new Set(creativeRows.map(r=>r.id));creativeRows.push(...data.cards.filter(r=>!ids.has(r.id)));creativeAfter=data.after;creativeComplete=data.complete;
  $('#creative-source').textContent=(state.demoMode?'虚构示例关联 · 非平台数据 · 展示时间 ':'Meta 只读关联 · 获取时间 ')+when(data.capturedAt)+'（北京时间） · 未修改广告';paintCreatives();loadCreativePerformance(force);loadLearning();
 }catch(err){if(view==='creatives'&&request===creativeRequest){$('#creative-source').textContent='读取未完成：'+err.message;$('#creative-more').hidden=!creativeAfter;$('#creative-more').disabled=false;await storedMonitorFallback(selected,request);}}
}
function paintCreatives(){
 if(creativeRows.some(r=>r.offlineOnly)){paintStoredMonitors();return;}
 if(view!=='creatives'||!$('#creative-grid'))return;const q=creativeQuery.toLowerCase();const rows=creativeRows.filter(r=>(!creativeCampaign||r.campaignId===creativeCampaign)&&(!q||[r.name,r.id,r.creativeId,...r.texts,...r.titles].join(' ').toLowerCase().includes(q)));
 $('#creative-context').textContent=creativeCampaign?'筛选系列 ID：'+creativeCampaign:'当前账户的广告，包含平台返回的待投放及暂停广告';
 $('#creative-grid').innerHTML=rows.map(r=>`<article class="creative-card"><button class="creative-thumb" data-creative-id="${esc(r.id)}" aria-label="查看素材 ${esc(r.name)}">${r.images[0]?`<img src="${esc(r.images[0].thumbnailUrl||r.images[0].url)}" alt="${esc(r.name)} · ${esc(r.images[0].label)}" loading="lazy"><span class="creative-image-error" hidden>图片暂不可用，请重新读取</span>`:'<span>平台尚未提供可预览图片</span>'}</button><div class="creative-info"><h3>${esc(r.name)}</h3><p class="fine">${esc(r.storageLabel||'平台远程预览')} · ${esc(r.effectiveStatus||r.status||'状态未知')} · ${r.videoId?'视频封面':'图片素材'} · ${r.images.length} 张预览</p><p class="fine">广告 ID：${esc(r.id)}</p>${performanceBlock(r.id)}<p>${esc(r.titles[0]||'')}</p><p class="creative-copy">${esc(r.texts[0]||'平台未返回正文')}</p><button class="text-button" data-creative-id="${esc(r.id)}">图片与完整文案 →</button></div><section class="learning-card" data-learning-ad="${esc(r.id)}">${learningBlock(r)}</section></article>`).join('')||'<p class="empty">当前已载入广告中没有匹配项。'+(!creativeComplete?'可继续加载下一页，尚未检索全部广告。':'平台未返回匹配广告。')+'</p>';
 $('#creative-count').textContent='已载入 '+creativeRows.length+' 条广告 · 当前显示 '+rows.length+' 条 · '+(creativeComplete?'本次查询分页完成':'尚有下一页，搜索只覆盖已载入广告');$('#creative-more').hidden=!creativeAfter;$('#creative-more').disabled=false;paintPerformanceDetail();
}
function openCreative(adId){const r=creativeRows.find(x=>x.id===adId);if(!r)return;
 $('#detail-content').innerHTML=`<div class="dialog-title"><h2>广告素材预览</h2><button class="close" data-close="detail-dialog" aria-label="关闭">×</button></div><h3>${esc(r.name)}</h3><p class="fine">广告 ID：${esc(r.id)}<br>创意 ID：${esc(r.creativeId||'未返回')}<br>系列 ID：${esc(r.campaignId||'未返回')} · ${esc(r.effectiveStatus||r.status||'状态未知')}</p>${(r.localMedia||[]).filter(a=>a.kind==='video').map(a=>`<video controls preload="metadata" style="width:100%;max-height:70vh" src="${esc(a.playbackUrl)}" ${a.previewReady?'poster="'+esc(a.previewUrl)+'"':''}></video>`).join('')}${r.videoId&&!(r.localMedia||[]).some(a=>a.kind==='video')?'<p class="notice">平台远程封面；原视频尚未本地归档。</p>':''}<div class="creative-images">${r.images.map(i=>`<figure><img src="${esc(i.url)}" alt="${esc(r.name)} · ${esc(i.label)}"><span class="creative-image-error" hidden>图片暂不可用，请关闭后重新读取</span><figcaption>${esc(i.label)}</figcaption></figure>`).join('')||'<p>平台未返回图片，不能推测素材。</p>'}</div>${r.unresolvedImages?'<p class="notice">另有 '+r.unresolvedImages+' 个图片引用未返回可预览地址，以上不代表完整变体清单。</p>':''}${performanceBlock(r.id)}<h3>标题</h3>${r.titles.map(t=>`<p>${esc(t)}</p>`).join('')||'<p>未返回</p>'}<h3>广告正文</h3>${r.texts.map(t=>`<p style="white-space:pre-wrap">${esc(t)}</p>`).join('')||'<p>未返回</p>'}<h3>落地页</h3>${r.destinations.map(u=>`<p><a href="${esc(u)}" target="_blank" rel="noreferrer noopener">${esc(u)}</a></p>`).join('')||'<p>未返回</p>'}<p class="fine">当前创意关联预览；不证明某个素材版本已产生展示或转化。</p>`;$('#detail-dialog').showModal();
}
document.addEventListener('click',e=>{const show=e.target.closest('[data-creative-id]');if(show){openCreative(show.dataset.creativeId);return;}const campaign=e.target.closest('[data-campaign-creatives]');if(campaign){creativeCampaign=campaign.dataset.campaignCreatives;creativeQuery='';$('#detail-dialog').close();view='creatives';render();return;}if(e.target.closest('#creative-clear')){creativeCampaign='';paintCreatives();}if(e.target.closest('#creative-refresh'))renderCreatives(false,true);if(e.target.closest('#creative-more')){e.target.disabled=true;renderCreatives(true);}});
document.addEventListener('input',e=>{if(e.target.id==='creative-search'){creativeQuery=e.target.value;paintCreatives();}});
document.addEventListener('change',async e=>{if(e.target.id==='creative-account'){accountId=e.target.value;snapshotId=null;creativeCampaign='';creativeQuery='';try{await refresh();}catch(err){toast(err.message,true);}}});
document.addEventListener('error',e=>{if(e.target.matches?.('.creative-thumb img,.creative-images img,.historical-creative img')){e.target.hidden=true;const message=e.target.parentElement.querySelector('.creative-image-error');if(message)message.hidden=false;}},true);
const creativeStyle=document.createElement('style');creativeStyle.textContent='.creative-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px}.creative-card{border:1px solid #dce2e8;border-radius:12px;overflow:hidden;background:#fff}.creative-thumb{width:100%;height:300px;display:flex;align-items:center;justify-content:center;background:#f3f1ed;border:0;cursor:zoom-in;padding:8px}.creative-thumb img{width:100%;height:100%;object-fit:contain}.creative-info{padding:16px;overflow-wrap:anywhere}.creative-info h3{margin:0 0 8px}.creative-copy{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.creative-images{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.creative-images figure{margin:0}.creative-images img{width:100%;max-height:70vh;object-fit:contain;background:#f3f1ed}.creative-image-error{padding:24px;color:#8b2734}.creative-image-error[hidden]{display:none}';document.head.append(creativeStyle);


// Performance dates and state are separate from current creative metadata.
let performanceSince='',performanceUntil='',performanceGeneration=0,performanceState={status:'loading',rows:new Map()};
function performanceToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:detail?.account.timezone||'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function performancePreset(days){performanceUntil=performanceToday();const start=new Date(performanceUntil+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-(days-1));performanceSince=start.toISOString().slice(0,10);}
function performanceControls(){if(!performanceSince){if(state.demoMode)performanceSince=performanceUntil='2026-10-01';else performancePreset(7);}return `<div class="performance-controls"><label>开始日期<input id="performance-since" aria-label="指标开始日期" type="date" value="${esc(performanceSince)}" max="${esc(performanceToday())}"></label><label>结束日期<input id="performance-until" aria-label="指标结束日期" type="date" value="${esc(performanceUntil)}" max="${esc(performanceToday())}"></label><button class="secondary" data-performance-days="7">最近7天</button><button class="secondary" data-performance-days="30">最近30天</button><button class="primary" id="performance-update">更新指标</button></div><p id="performance-context" class="notice">正在读取图片旁的广告表现…</p><p class="fine">广告级合计（含全部素材变体），不代表单张图片独立归因。图片为当前创意，历史期间更换素材时请结合操作记录判断。当日数据未结算，购买可能延迟回传；购买样本很少时先观察，不据此判定素材优劣。</p>`;}
function performanceBlock(id){const state=performanceState,row=state.rows.get(id),shown=state.status==='ready'&&row;const currency=state.currency||'币种待核实';
 const values=[['花费 · '+currency,shown&&row.spend!==null?n(row.spend,2):'—'],['链接点击',shown?n(row.clicks):'—'],['网站购买',shown?n(row.purchases):'—'],['CPA · '+currency,shown&&row.spend!==null&&row.purchases>0?n(row.spend/row.purchases,2):'—'],['购买价值 · '+currency,shown?n(row.purchaseValue,2):'—'],['ROAS',shown?n(row.roas,2):'—']];
 return `<div data-performance-id="${esc(id)}"><div class="performance-metrics" aria-label="广告表现 ${esc(id)}">${values.map(([k,v])=>`<div><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><p class="fine performance-note">${state.status==='loading'?'指标读取中…':state.status==='error'?'指标读取失败，未按零处理':row?.status==='no_row'?'本期未返回投放记录，不按零处理':'广告合计 · '+esc(state.since||'')+' — '+esc(state.until||'')}</p></div>`;
}
function paintPerformanceDetail(){const el=$('#detail-content [data-performance-id]');if(el)el.outerHTML=performanceBlock(el.dataset.performanceId);}
async function loadCreativePerformance(force=false){
 if(view!=='creatives')return;if(!creativeRows.length){if($('#performance-context'))$('#performance-context').textContent='当前没有可匹配的广告，暂无指标。';return;}const generation=++performanceGeneration,account=creativeAccount,since=performanceSince,until=performanceUntil,ids=creativeRows.map(r=>r.id);
 performanceState={status:'loading',rows:new Map()};paintCreatives();const update=$('#performance-update');if(update)update.disabled=true;if($('#performance-context'))$('#performance-context').textContent='正在读取 '+since+' — '+until+' 的广告表现…';
 try{const rows=new Map();let context;for(let i=0;i<ids.length;i+=100){const result=await api('/api/creative-performance?account='+encodeURIComponent(account)+'&since='+since+'&until='+until+'&ads='+ids.slice(i,i+100).join(',')+(force?'&refresh=1':''));if(generation!==performanceGeneration||view!=='creatives'||creativeAccount!==account)return;
  if(context&&(context.currency!==result.currency||context.timezone!==result.timezone||context.since!==result.since||context.until!==result.until||context.attribution!==result.attribution))throw new Error('分批查询口径不一致，未展示混合结果');context=result;for(const row of result.rows)rows.set(row.adId,row);}
  performanceState={...context,status:'ready',rows};$('#performance-context').textContent=since+' — '+until+' · 账户时区 '+context.timezone+' · 币种 '+context.currency+' · '+context.attribution+' · 按展示日期归因 · 数据获取 '+when(context.capturedAt)+'（北京时间）';paintCreatives();
 }catch(err){if(generation===performanceGeneration&&view==='creatives'){performanceState={status:'error',rows:new Map()};$('#performance-context').textContent='指标未完成读取：'+err.message;paintCreatives();}}
 finally{if(generation===performanceGeneration&&$('#performance-update'))$('#performance-update').disabled=false;}
}
document.addEventListener('click',e=>{const preset=e.target.closest('[data-performance-days]');if(preset){performancePreset(Number(preset.dataset.performanceDays));$('#performance-since').value=performanceSince;$('#performance-until').value=performanceUntil;loadCreativePerformance(true);}if(e.target.closest('#performance-update')){performanceSince=$('#performance-since').value;performanceUntil=$('#performance-until').value;loadCreativePerformance(true);}});
const performanceStyle=document.createElement('style');performanceStyle.textContent='.creative-grid{grid-template-columns:repeat(auto-fill,minmax(min(100%,460px),1fr))}.creative-card{display:grid;grid-template-columns:40% minmax(0,1fr)}.creative-thumb{height:100%;min-height:300px}.creative-copy{-webkit-line-clamp:2}.performance-controls{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:16px 0}.performance-controls label{min-width:150px;flex:1}.performance-metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.performance-metrics>div{background:#f2f5f7;border-radius:8px;padding:10px}.performance-metrics small{display:block;color:#66717d;font-size:11px}.performance-metrics strong{display:block;font-size:20px;margin-top:5px;font-variant-numeric:tabular-nums}.performance-note{margin:8px 0}@media(max-width:560px){.creative-card{grid-template-columns:35% minmax(0,1fr)}.creative-info{padding:12px}.performance-metrics>div{padding:8px}.performance-metrics strong{font-size:18px}}';document.head.append(performanceStyle);

// Append-only casebook; ad identity and historical context stay separate from date filters.
let learningData=new Map(),learningAccount='',learningGeneration=0,learningStatus='loading';
const learningNames={facts:'已核实事实',hypotheses:'待验证假设',suggestions:'建议（未执行）',approvals:'用户批准记录',executions:'实际执行记录',verification:'验证结果'};
const learningTime=x=>x?new Date(x).toLocaleString('zh-CN',{timeZone:'America/Los_Angeles',hour12:false})+'（太平洋时间）':'待核实';
function learningSections(c){return Object.entries(learningNames).map(([k,name])=>`<div class="learning-section"><h5>${name}</h5>${c[k]?.length?'<ul>'+c[k].map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p class="fine">暂无记录，不推定已批准、已执行或已验证。</p>'}</div>`).join('');}
function learningMetrics(m){if(!m)return '';const fields=[['spend','花费'],['impressions','展示'],['frequency','频次'],['clicks','链接点击'],['ctr','链接CTR %'],['cpc','链接CPC'],['landingViews','落地页浏览'],['addToCart','加购'],['checkouts','结账'],['purchases','网站购买'],['cpa','CPA'],['purchaseValue','购买价值'],['roas','ROAS']];return `<div class="notice">历史数据期间 ${esc(m.since||'未记录')} — ${esc(m.until||'未记录')} · ${esc(m.timezone||'时区待核实')} · ${esc(m.currency||'币种待核实')} · ${esc(m.attribution||'归因待核实')} · ${esc(m.basis||'日期口径待核实')}<br>采集时间：${esc(learningTime(m.capturedAt))}</div><div class="learning-metric-grid">${fields.map(([k,label])=>`<div><small>${label}</small><strong>${n(m[k],['spend','cpc','cpa','purchaseValue','roas','frequency','ctr'].includes(k)?2:0)}</strong></div>`).join('')}</div><p class="fine">${esc(m.note||'缺失不按零处理；平台归因不等于已核实独立订单。')}</p>`;}
function learningBody(record){const c=record.content;return `${c.summary?`<p class="learning-summary">${esc(c.summary)}</p>`:''}${c.assetSha?`<figure class="historical-creative"><img loading="lazy" src="/api/learning/asset?account=${esc(record.accountId)}&ad=${esc(record.adId)}&sha=${esc(c.assetSha)}" alt="当时批准的素材"><span class="creative-image-error" hidden>历史图片暂不可用，请保留此记录并检查归档。</span><figcaption>${esc(c.assetNote||'当时批准素材；不证明每个日期实际投放均使用此版本')}</figcaption></figure>`:'<p class="fine">本记录未保存可确认的历史图片；上方是当前创意，不能冒充当时素材。</p>'}${c.settings?.length?`<h4>广告结构 · 逐框理解</h4><p class="fine">${esc(c.settingsContext||'当时设置；不是当前配置的实时证明。理由为回顾解释，未保存的原始决策不推测。')}</p><div class="learning-settings">${c.settings.map(s=>`<div class="setting-row"><span class="tag gray">${esc(s.level)}</span><h5>${esc(s.field)}：${esc(s.value??'待核实')}</h5><p><b>为什么：</b>${esc(s.reason||'当时原因未记录')}</p><p><b>影响：</b>${esc(s.effect||'待补充')}</p><p><b>何时复查：</b>${esc(s.recheck||'待补充')}</p></div>`).join('')}</div>`:''}${learningMetrics(c.metrics)}${learningSections(c)}${c.nextReview?`<p class="notice"><b>下一次复查：</b>${esc(c.nextReview)}</p>`:''}${c.history?.length?`<h4>历史案例对照</h4>${c.history.map(h=>`<article class="history-example"><h5>${esc(h.title)}</h5><p>${esc(h.period)} · ${esc(h.context)}</p><p>${esc(h.metrics)}</p><p><b>可参考：</b>${esc(h.lesson)}</p><p><b>不能直接套用：</b>${esc(h.limit)}</p><p class="fine">来源：${esc(h.source)}</p></article>`).join('')}`:''}${c.evidence?.length?`<p class="fine">证据：${c.evidence.map(esc).join('；')}</p>`:''}`;}
function learningBlock(ad){const records=learningAccount===creativeAccount?learningData.get(ad.id)||[]:[];return `<div class="learning-heading"><h3>投放思路与学习复盘</h3><button class="secondary" data-learning-refresh="${esc(ad.id)}">刷新记录</button></div><p class="fine">教学按日期完整展开；上方指标随日期筛选变化，以下历史记录保留当时口径。记录建议不会改变广告。</p>${learningStatus==='error'&&learningAccount===creativeAccount?'<p class="notice">学习记录读取失败，请刷新记录；不代表没有历史。</p>':records.length?records.map(r=>`<article class="learning-entry"><div class="learning-heading"><h4>${esc(r.recordDate)} · ${esc(r.title)}</h4><span class="tag gray">${r.kind==='case'?'初始案例':r.kind==='correction'?'纠错版本':'复盘记录'}</span></div><p class="fine">记录人：${esc(r.author)} · 录入 ${esc(learningTime(r.createdAt))}<br>证据来源：${esc(r.source)}<br>数据库：已保存并回读 · NAS备份（回读校验）：${r.storage.nas==='verified'?'已归档并校验':'待归档，数据库记录已保留'}${r.storage.nasVerifiedAt?' · '+esc(learningTime(r.storage.nasVerifiedAt)):''}${r.supersedes?'<br>本条纠正版本 '+esc(r.supersedes)+'；原记录保留。':''}</p>${learningBody(r)}</article>`).join(''):learningStatus==='loading'?'<p>正在读取学习记录…</p>':'<p class="notice">教学记录待补充。尚未记录当时决策原因，不根据当前表现倒推。</p>'}<div class="learning-actions"><button class="secondary" data-learning-note="judgment" data-ad="${esc(ad.id)}">补充我的判断</button><button class="secondary" data-learning-note="followup" data-ad="${esc(ad.id)}">追加复查结果</button><button class="secondary" data-learning-note="correction" data-ad="${esc(ad.id)}">追加纠错版本</button></div>`;}
function paintLearning(){if(view!=='creatives')return;document.querySelectorAll('[data-learning-ad]').forEach(el=>{const ad=creativeRows.find(r=>r.id===el.dataset.learningAd);if(ad)el.innerHTML=learningBlock(ad);});}
async function loadLearning(){const generation=++learningGeneration,account=creativeAccount,ids=creativeRows.map(r=>r.id);if(!ids.length)return;if(learningAccount!==account){learningAccount=account;learningData=new Map();}learningStatus='loading';paintLearning();try{const result=[];for(let i=0;i<ids.length;i+=100){const r=await api('/api/learning?account='+encodeURIComponent(account)+'&ads='+ids.slice(i,i+100).join(','));result.push(...r.records);}if(view!=='creatives'||generation!==learningGeneration||creativeAccount!==account)return;learningData=new Map(ids.map(id=>[id,result.filter(r=>r.accountId===account&&r.adId===id)]));learningStatus='ready';paintLearning();}catch(e){if(generation===learningGeneration&&account===creativeAccount){learningStatus='error';paintLearning();}}}
function openLearningNote(adId,kind){const ad=creativeRows.find(r=>r.id===adId);if(!ad)return;const labels={library:'本地图库',judgment:'补充我的判断',followup:'追加复查结果',correction:'追加纠错版本'},records=learningData.get(adId)||[];if(kind==='correction'&&!records.length){toast('请先读取需要纠错的历史记录',true);return;}
 $('#detail-content').innerHTML=`<div class="dialog-title"><h2>${labels[kind]}</h2><button class="close" data-close="detail-dialog" aria-label="关闭">×</button></div><p>${esc(ad.name)} · ${esc(adId)}</p><p class="notice">只追加学习记录，不执行广告修改。批准与执行是你的历史陈述，需写明来源，不会触发平台操作。不要填写密码、Cookie或密钥。</p><form id="learning-form"><label>记录日期（太平洋时间）<input type="date" name="recordDate" required value="${performanceToday()}"></label><label>标题<input name="title" required maxlength="200" value="${labels[kind]}"></label><label>证据来源<input name="source" required maxlength="1000" placeholder="例如：今天的 Meta 报表、商店订单核对、我的观察"></label>${kind==='correction'?`<label>纠正哪条记录<select name="supersedes">${records.map(r=>`<option value="${esc(r.hash)}">${esc(r.recordDate+' '+r.title)}</option>`).join('')}</select></label>`:''}${Object.entries(learningNames).map(([k,t])=>`<label>${t}<textarea name="${k}" rows="2" maxlength="4000" placeholder="没有就留空；每行一项"></textarea></label>`).join('')}<label>下一次复查条件<textarea name="nextReview" rows="2" maxlength="2000"></textarea></label><button type="submit" class="primary">追加保存并回读</button><p id="learning-save-result" role="status"></p></form>`;
 const form=$('#learning-form'),key='user-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(12)),x=>x.toString(16).padStart(2,'0')).join(''),account=creativeAccount;form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),resultNode=form.querySelector('#learning-save-result');button.disabled=true;const data=new FormData(form),content={};for(const k of Object.keys(learningNames))content[k]=String(data.get(k)||'').split('\n').map(t=>t.trim()).filter(Boolean);content.nextReview=String(data.get('nextReview')||'');const b={accountId:account,campaignId:ad.campaignId,adsetId:ad.adsetId,adId,recordKey:key,recordDate:data.get('recordDate'),kind,title:data.get('title'),source:data.get('source'),content,...(kind==='correction'?{supersedes:data.get('supersedes')}:{})};try{const saved=await post('/api/learning',b),read=await api('/api/learning?account='+account+'&ads='+adId);if(!read.records.some(r=>r.hash===saved.record.hash))throw new Error('数据库回读未确认，请保留内容重试');resultNode.textContent='数据库已保存并回读；NAS '+(saved.record.storage.nas==='verified'?'已归档并校验':'待服务器备份程序同步，可稍后刷新记录查看');button.textContent='已保存';await loadLearning();}catch(err){resultNode.textContent='未确认完整保存：'+err.message;button.disabled=false;}});$('#detail-dialog').showModal();
}
document.addEventListener('click',e=>{const note=e.target.closest('[data-learning-note]');if(note)openLearningNote(note.dataset.ad,note.dataset.learningNote);if(e.target.closest('[data-learning-refresh]'))loadLearning();});
const learningStyle=document.createElement('style');learningStyle.textContent=`.creative-grid{grid-template-columns:1fr}.creative-card{grid-template-columns:minmax(220px,30%) minmax(0,1fr)}.creative-thumb{height:420px;min-height:0;align-self:start}.learning-card{grid-column:1/-1;padding:24px;border-top:1px solid #dce2e8;background:#fafbf9}.learning-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.learning-heading h3,.learning-heading h4{margin:8px 0}.learning-entry{border-left:3px solid #8a3543;padding:8px 20px 24px;margin:24px 0;background:white}.learning-section h5,.setting-row h5,.history-example h5{font-size:15px;margin:12px 0 6px}.learning-section p,.setting-row p,.history-example p{margin:5px 0;line-height:1.7}.learning-settings{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.setting-row,.history-example{border:1px solid #e1e6e6;padding:16px;border-radius:8px}.history-example{margin:12px 0}.learning-metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:8px}.learning-metric-grid>div{background:#f1f4f5;padding:10px;border-radius:6px}.learning-metric-grid small,.learning-metric-grid strong{display:block}.learning-actions{display:flex;gap:10px;flex-wrap:wrap}.historical-creative{margin:12px 0}.historical-creative img{max-width:240px;max-height:300px;object-fit:contain}.historical-creative figcaption{font-size:12px;color:#67737a}#learning-form label{display:block;margin:14px 0}#learning-form input,#learning-form textarea,#learning-form select{width:100%}@media(max-width:600px){.creative-card{grid-template-columns:1fr}.creative-thumb{height:320px}.learning-card{padding:12px}.learning-entry{padding:8px 12px}.learning-settings{grid-template-columns:1fr}.learning-metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.learning-card p,.learning-card li{overflow-wrap:anywhere}}`;document.head.append(learningStyle);

let libraryGeneration=0,libraryAssets=[],libraryAfter='';
const libraryNav=document.createElement('button');libraryNav.dataset.view='library';libraryNav.textContent='本地图库';$('#nav').append(libraryNav);
async function renderLibrary(more=false){const gen=++libraryGeneration,account=accountId;const c=$('#content');if(!more){libraryAssets=[];libraryAfter='';c.innerHTML=`<article class="panel"><h2>本地图库</h2><p>本地原始素材；广告效果请在「广告与素材」按广告查看。未确认的广告关联不会推测匹配。</p><label>广告账户 <select id="library-account">${allAccounts().map(a=>`<option value="${esc(a.id)}" ${a.id===accountId?'selected':''}>${esc(a.name||a.id)} · ${esc(a.id)}</option>`).join('')}</select></label><select id="library-kind"><option value="all">图片与视频</option><option value="image">图片</option><option value="video">视频</option></select><p id="library-storage">读取存储状态…</p><div id="library-grid" class="creative-grid"></div><button id="library-more" hidden>继续加载</button></article>`;}const kind=$('#library-kind')?.value||'all';try{const r=await api('/api/local-assets?account='+account+'&kind='+kind+'&after='+encodeURIComponent(libraryAfter));if(view!=='library'||gen!==libraryGeneration||account!==accountId)return;libraryAssets.push(...r.assets);libraryAfter=r.after||'';$('#library-grid').innerHTML=libraryAssets.map(a=>`<article class="panel"><p>${esc(a.source)} · ${a.kind==='video'?'视频':'图片'}</p>${a.previewStatus==='failed'?'<p class="notice">原片已保留；封面或播放版生成失败，需要复查。</p>':''}${a.kind==='video'?`<video controls preload="metadata" style="width:100%;max-height:320px" src="${esc(a.playbackUrl)}" ${a.previewReady?'poster="'+esc(a.previewUrl)+'"':''}></video>`:`<a href="${esc(a.url)}" target="_blank" rel="noopener"><img src="${esc(a.previewReady?a.previewUrl:a.url)}" alt="已归档图片" loading="lazy" style="width:100%;height:280px;object-fit:contain"></a>`}<p class="fine" style="overflow-wrap:anywhere">${esc(a.association)} · ${n(a.bytes/1048576,2)} MB<br>${esc(a.mediaIdentity)}<br>SHA-256 ${esc(a.sha256)}</p></article>`).join('')||'<p>当前账户没有符合筛选的本地已验证素材。</p>';$('#library-more').hidden=!libraryAfter;const status=await api('/api/storage');if(view!=='library'||gen!==libraryGeneration)return;const last=status.backups[0];$('#library-storage').textContent='主存储：服务器本地；备份：NAS。最近备份：'+(last?({verified:'已备份并校验',running:'备份中',failed:'失败'}[last.status]||last.status)+' · '+when(last.created_at)+(last.payload.restoreVerified?' · 已验证恢复':' · 恢复验证待完成'):'尚无备份回执');const bw=status.workers.find(w=>w.id==='backup_worker'),mw=status.workers.find(w=>w.id==='media_worker');if(bw&&bw.payload.status!=='healthy')$('#library-storage').textContent+='；备份程序：需要复查（'+when(bw.updated_at)+'）';if(mw?.payload.reason==='disk_space_guard')$('#library-storage').textContent+='；磁盘余量不足，下载已等待';if(mw?.payload.freeBytes!==undefined)$('#library-storage').textContent+='；可用 '+n(mw.payload.freeBytes/1073741824,1)+' GiB，下载停止线 '+n(mw.payload.stopBelowBytes/1073741824,1)+' GiB';}catch(e){if(view==='library'&&gen===libraryGeneration)toast(e.message,true);}}
document.addEventListener('click',e=>{if(e.target.closest('#library-more'))renderLibrary(true);});
document.addEventListener('change',e=>{if(e.target.id==='library-kind'){libraryAfter='';libraryAssets=[];renderLibrary(true);}});

document.addEventListener('change',async e=>{if(e.target.id==='library-account'){accountId=e.target.value;snapshotId=null;try{await refresh();}catch(err){toast(err.message,true);}}});

document.addEventListener('click',e=>{if(e.target.closest('[data-open-local-library]')){view='library';render();}});

async function loadDailyReviewState(account,request){try{const d=await api('/api/daily-review/status?account='+account);if(view!=='creatives'||request!==creativeRequest||account!==creativeAccount)return;const el=$('#daily-review-state');if(!el)return;if(!d.schedule.enabled||!d.schedule.monitors.length){el.textContent='当前账户未配置服务器每日复盘。';return;}const latest=d.runs[0];let text='服务器：每天09:00（America/Los_Angeles）规则复盘；失败后10/12/15点重试；建议不会执行。';if(latest){text+=' 最近'+(latest.slot==='trial'?'试运行':'定时检查')+'：'+latest.review_date+' · '+({recorded:'数据库已保存并回读',failed:'检查未完成，缺失不按零',ready:'数据已保存，学习记录待确认',collecting:'采集中'}[latest.status]||latest.status)+' · '+when(latest.updated_at)+'（北京时间）。';text+=latest.record_hash?(latest.nas_verified_at?' NAS已归档并回读。':' NAS待归档，数据库已保留。'):'';if(latest.error_code)text+=' 异常：'+latest.error_code+'。';}else text+=' 尚无执行回执。';if(d.serverHour>=10&&!d.runs.some(r=>r.review_date===d.serverToday&&r.slot==='daily'&&r.status==='recorded'))text+=' 今日定时检查尚无成功回执，需复查。';el.textContent=text;}catch{if(view==='creatives'&&request===creativeRequest&&$('#daily-review-state'))$('#daily-review-state').textContent='服务器复盘状态暂不可读，不能视为正常完成。';}}
async function storedMonitorFallback(account,request){try{const d=await api('/api/daily-review/status?account='+account);if(view!=='creatives'||request!==creativeRequest||account!==creativeAccount||!d.schedule.monitors.length)return;creativeRows=d.schedule.monitors.map(m=>({id:m.adId,name:m.label||'已保存的监控对象',campaignId:m.campaignId,adsetId:m.adsetId,offlineOnly:true,images:[],texts:[],titles:[],destinations:[]}));creativeAfter=null;creativeComplete=true;paintStoredMonitors();loadLearning();}catch{/* Original failure notice remains; no success inferred. */}}
function paintStoredMonitors(){if(view!=='creatives'||!$('#creative-grid'))return;const q=creativeQuery.toLowerCase();const rows=creativeRows.filter(r=>[r.name,r.id].join(' ').toLowerCase().includes(q));$('#creative-grid').innerHTML=rows.map(r=>`<article class="creative-card"><div class="creative-info"><h3>${esc(r.name)}（配置名称）</h3><p>实时素材与投放状态未读取；以下仅显示服务器保存的历史学习记录，不推测当前图片、状态或指标。</p><p>广告ID：${esc(r.id)}</p></div><section class="learning-card" data-learning-ad="${esc(r.id)}">${learningBlock(r)}</section></article>`).join('');$('#creative-count').textContent='仅显示已配置监控对象的存储记录；实时平台读取未完成。';$('#creative-more').hidden=true;}
